+const { pathToRegexp } = require('/workspace/repo/node_modules/.pnpm/path-to-regexp@6.3.0/node_modules/path-to-regexp/dist/index.js');
+function isPathMatchingRoute({ currentRoute, exact, path: viewPath, sensitive, strict }) {
+  if (!viewPath) return false;
+  if (exact) {
+    const regex = pathToRegexp(viewPath, [], { end: true, sensitive, strict });
+    return regex.test(currentRoute);
+  }
+  let route = currentRoute, path = viewPath;
+  if (!sensitive) { route = route.toLowerCase(); path = path.toLowerCase(); }
+  if (!strict) {
+    if (route.length > 1 && route.endsWith('/')) route = route.slice(0, -1);
+    if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
+  }
+  if (route === path) return true;
+  if (route.startsWith(path)) {
+    const rem = route.slice(path.length);
+    if (strict && rem === '/') return false;
+    return rem.startsWith('/');
+  }
+  return false;
+}
+const T = (desc, got, exp) => console.log((got===exp?'PASS':'FAIL')+' '+desc+' => '+got);
