+T('undefined path', isPathMatchingRoute({currentRoute:'/x',path:undefined}), false);
+T('empty path', isPathMatchingRoute({currentRoute:'/x',path:''}), false);
+// case
+T('case-insensitive default', isPathMatchingRoute({currentRoute:'/Dashboard',path:'/dashboard'}), true);
+T('case-sensitive', isPathMatchingRoute({currentRoute:'/Dashboard',path:'/dashboard',sensitive:true}), false);
+// trailing slash tolerance
+T('trailing tolerant route/', isPathMatchingRoute({currentRoute:'/dashboard/',path:'/dashboard'}), true);
